// Typed access to the sanitised, offline-imported Notion source.
//
// The JSON is generated by scripts/import-notion-statistics.mjs. Blocks are
// rendered as React elements; no raw exported HTML is ever injected.
import sourceJson from "@/content/statistics/source.json";
import { SECTION_BY_ID, type SectionMeta } from "@/lib/statistics/content";

export interface Inline {
  text?: string;
  strong?: boolean;
  em?: boolean;
  code?: boolean;
  math?: string;
  raw?: string;
  formulaKey?: string;
}

export type Block =
  | { type: "heading"; level: 1 | 2 | 3 | 4; text: string; anchor: string }
  | { type: "paragraph"; inline: Inline[] }
  | { type: "list"; ordered: boolean; items: Inline[][] }
  | { type: "quote"; inline: Inline[] }
  | { type: "callout"; tone: string; icon: string; blocks: Block[] }
  | { type: "toggle"; summary: string; blocks: Block[] }
  | { type: "table"; headers: Inline[][]; rows: Inline[][][] }
  | { type: "code"; language: string; text: string }
  | { type: "formula"; tex: string; raw: string; alt: string }
  | { type: "divider" };

export interface SourceHeading {
  level: number;
  text: string;
  anchor: string;
}

export interface SourceCounts {
  paragraphs: number;
  lists: number;
  listItems: number;
  tables: number;
  tableRows: number;
  formulas: number;
  headings: number;
  toggles: number;
  callouts: number;
  code: number;
}

export interface SourceSection {
  id: string;
  number: number;
  title: string;
  titleEn: string;
  anchor: string;
  sourceSequence: number;
  counts: SourceCounts;
  formulaCount: number;
  textLength: number;
  headings: SourceHeading[];
  subsections: SourceHeading[];
  blocks: Block[];
}

export interface SourceDocument {
  generatedBy: string;
  schemaVersion: number;
  title: string;
  source: {
    file: string;
    relativePath: string;
    notionId: string | null;
    canonicalUrl: string | null;
    sha256: string;
    bytes: number;
    observedModified: string;
    exportShape: string;
    note: string;
  };
  toc: { text: string; href: string }[];
  intro: Block[];
  sections: SourceSection[];
  counts: {
    htmlFiles: number;
    sections: number;
    headings: number;
    subsections: number;
    paragraphs: number;
    lists: number;
    listItems: number;
    tables: number;
    tableRows: number;
    toggles: number;
    formulas: number;
    uniqueFormulas: number;
    codeBlocks: number;
    textCharacters: number;
    figures: number;
    assets: number;
  };
  formulas: { section: string; raw: string; tex: string; matched: boolean }[];
  unmappedFormulas: unknown[];
  assets: unknown[];
  unresolved: unknown[];
}

export const SOURCE = sourceJson as unknown as SourceDocument;

export const SOURCE_SECTIONS = SOURCE.sections;
export const SOURCE_SECTION_BY_NUMBER = new Map(
  SOURCE_SECTIONS.map((section) => [section.number, section]),
);

export function sourceSection(number: number): SourceSection {
  const section = SOURCE_SECTION_BY_NUMBER.get(number);
  if (!section) throw new Error(`Source section §${number} is missing from source.json`);
  return section;
}

export function sectionMetaFor(number: number): SectionMeta {
  const meta = SECTION_BY_ID.get(`s${number}`);
  if (!meta) throw new Error(`Section metadata for §${number} is missing from content.ts`);
  return meta;
}

export const SOURCE_STATS = {
  ...SOURCE.counts,
  sourceFile: SOURCE.source.file,
  sha256: SOURCE.source.sha256,
  observedModified: SOURCE.source.observedModified,
  notionUrl: SOURCE.source.canonicalUrl,
  exportShape: SOURCE.source.exportShape,
};

export function inlineText(inline: readonly Inline[]): string {
  return inline.map((node) => (node.math ? ` ${node.raw ?? node.math} ` : (node.text ?? ""))).join("").trim();
}

/** Plain text for search snippets and reading-time estimates. */
export function blocksText(blocks: readonly Block[]): string {
  let text = "";
  for (const block of blocks) {
    switch (block.type) {
      case "heading":
      case "code":
        text += ` ${block.type === "heading" ? block.text : block.text}`;
        break;
      case "paragraph":
      case "quote":
        text += ` ${inlineText(block.inline)}`;
        break;
      case "list":
        text += ` ${block.items.map((item) => inlineText(item)).join(" ")}`;
        break;
      case "table":
        text += ` ${block.headers.map((cell) => inlineText(cell)).join(" ")}`;
        text += ` ${block.rows.map((row) => row.map((cell) => inlineText(cell)).join(" ")).join(" ")}`;
        break;
      case "callout":
      case "toggle":
        text += ` ${block.type === "toggle" ? block.summary : ""} ${blocksText(block.blocks)}`;
        break;
      case "formula":
        text += ` ${block.raw}`;
        break;
      default:
        break;
    }
  }
  return text.trim();
}
